// 開啟或建立資料庫
const db = SQLite.openDatabaseSync('emogo.db');

// 初始化資料庫表格
export const initDatabase = () => {
  try {
    // 建立情緒問卷記錄表
    db.execSync(`
      CREATE TABLE IF NOT EXISTS sentiment_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        valence INTEGER NOT NULL,
        arousal INTEGER NOT NULL,
        dominance INTEGER NOT NULL,
        notes TEXT
      );
    `);

    // 建立 vlog 記錄表
    db.execSync(`
      CREATE TABLE IF NOT EXISTS vlog_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        video_uri TEXT NOT NULL,
        duration INTEGER NOT NULL
      );
    `);

    // 建立 GPS 記錄表
    db.execSync(`
      CREATE TABLE IF NOT EXISTS gps_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        accuracy REAL
      );
    `);

    console.log('✅ Database initialized successfully');
  } catch (error) {
    console.error('❌ Database initialization error:', error);
  }
};

// 插入情緒問卷記錄
export const insertSentimentRecord = (valence, arousal, dominance, notes = '') => {
  try {
    const timestamp = new Date().toISOString();
    const result = db.runSync(
      'INSERT INTO sentiment_records (timestamp, valence, arousal, dominance, notes) VALUES (?, ?, ?, ?, ?)',
      [timestamp, valence, arousal, dominance, notes]
    );
    console.log('✅ Sentiment record inserted:', result.lastInsertRowId);
    return result.lastInsertRowId;
  } catch (error) {
    console.error('❌ Error inserting sentiment record:', error);
    return null;
  }
};

// 插入 vlog 記錄
export const insertVlogRecord = (videoUri, duration) => {
  try {
    const timestamp = new Date().toISOString();
    const result = db.runSync(
      'INSERT INTO vlog_records (timestamp, video_uri, duration) VALUES (?, ?, ?)',
      [timestamp, videoUri, duration]
    );
    console.log('✅ Vlog record inserted:', result.lastInsertRowId);
    return result.lastInsertRowId;
  } catch (error) {
    console.error('❌ Error inserting vlog record:', error);
    return null;
  }
};

// 插入 GPS 記錄
export const insertGpsRecord = (latitude, longitude, accuracy = null) => {
  try {
    const timestamp = new Date().toISOString();
    const result = db.runSync(
      'INSERT INTO gps_records (timestamp, latitude, longitude, accuracy) VALUES (?, ?, ?, ?)',
      [timestamp, latitude, longitude, accuracy]
    );
    console.log('✅ GPS record inserted:', result.lastInsertRowId);
    return result.lastInsertRowId;
  } catch (error) {
    console.error('❌ Error inserting GPS record:', error);
    return null;
  }
};

// 取得所有情緒記錄
export const getAllSentimentRecords = () => {
  try {
    const records = db.getAllSync('SELECT * FROM sentiment_records ORDER BY timestamp DESC');
    return records;
  } catch (error) {
    console.error('❌ Error fetching sentiment records:', error);
    return [];
  }
};

// 取得所有 vlog 記錄
export const getAllVlogRecords = () => {
  try {
    const records = db.getAllSync('SELECT * FROM vlog_records ORDER BY timestamp DESC');
    return records;
  } catch (error) {
    console.error('❌ Error fetching vlog records:', error);
    return [];
  }
};

// 取得所有 GPS 記錄
export const getAllGpsRecords = () => {
  try {
    const records = db.getAllSync('SELECT * FROM gps_records ORDER BY timestamp DESC');
    return records;
  } catch (error) {
    console.error('❌ Error fetching GPS records:', error);
    return [];
  }
};

// 刪除所有記錄（用於測試）
export const clearAllData = () => {
  try {
    db.runSync('DELETE FROM sentiment_records');
    db.runSync('DELETE FROM vlog_records');
    db.runSync('DELETE FROM gps_records');
    console.log('✅ All data cleared');
  } catch (error) {
    console.error('❌ Error clearing data:', error);
  }
};

export default db;
"}

{"content": "import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { getAllSentimentRecords, getAllVlogRecords, getAllGpsRecords } from './database';

// 匯出所有資料為 JSON 檔案
export const exportAllData = async () => {
  try {
    const sentimentRecords = getAllSentimentRecords();
    const vlogRecords = getAllVlogRecords();
    const gpsRecords = getAllGpsRecords();

    const data = {
      exportDate: new Date().toISOString(),
      sentimentRecords,
      vlogRecords,
      gpsRecords,
      stats: {
        totalSentiment: sentimentRecords.length,
        totalVlogs: vlogRecords.length,
        totalGPS: gpsRecords.length,
      }
    };

    const fileName = `emogo_data_${Date.now()}.json`;
    const fileUri = FileSystem.documentDirectory + fileName;

    await FileSystem.writeAsStringAsync(fileUri, JSON.stringify(data, null, 2));

    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(fileUri);
      console.log('✅ Data exported and shared successfully');
      return true;
    } else {
      console.log('⚠️ Sharing not available on this device');
      return false;
    }
  } catch (error) {
    console.error('❌ Error exporting data:', error);
    return false;
  }
};

// 匯出個別資料類型
export const exportSentimentData = async () => {
  try {
    const records = getAllSentimentRecords();
    const fileName = `sentiment_data_${Date.now()}.json`;
    const fileUri = FileSystem.documentDirectory + fileName;

    await FileSystem.writeAsStringAsync(fileUri, JSON.stringify(records, null, 2));

    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(fileUri);
      return true;
    }
    return false;
  } catch (error) {
    console.error('❌ Error exporting sentiment data:', error);
    return false;
  }
};

export const exportVlogData = async () => {
  try {
    const records = getAllVlogRecords();
    const fileName = `vlog_data_${Date.now()}.json`;
    const fileUri = FileSystem.documentDirectory + fileName;

    await FileSystem.writeAsStringAsync(fileUri, JSON.stringify(records, null, 2));

    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(fileUri);
      return true;
    }
    return false;
  } catch (error) {
    console.error('❌ Error exporting vlog data:', error);
    return false;
  }
};

export const exportGpsData = async () => {
  try {
    const records = getAllGpsRecords();
    const fileName = `gps_data_${Date.now()}.json`;
    const fileUri = FileSystem.documentDirectory + fileName;

    await FileSystem.writeAsStringAsync(fileUri, JSON.stringify(records, null, 2));

    if (await Sharing.isAvailableAsync()) {
      await Sharing.shareAsync(fileUri);
      return true;
    }
    return false;
  } catch (error) {
    console.error('❌ Error exporting GPS data:', error);
    return false;
