useEffect(() => {
  requestLocationPermission();
}, []);

const requestLocationPermission = async () => {
  try {
    const { status } = await Location.requestForegroundPermissionsAsync();
    setLocationPermission(status === 'granted');

    if (status === 'granted') {
      // 權限授予後立即取得位置
      await getCurrentLocation();
    } else {
      Alert.alert('需要權限', '請允許 APP 存取您的位置資訊');
    }
  } catch (error) {
    console.error('❌ Error requesting location permission:', error);
  }
};

const getCurrentLocation = async () => {
  try {
    console.log('🔍 正在取得位置...');
    const loc = await Location.getCurrentPositionAsync({
      accuracy: Location.Accuracy.High,
      timeInterval: 5000,
      distanceInterval: 0,
    });
    setLocation(loc);
    console.log('✅ Location obtained:', {
      lat: loc.coords.latitude,
      lng: loc.coords.longitude,
      accuracy: loc.coords.accuracy
    });
  } catch (error) {
    console.error('❌ Error getting location:', error);

    // 如果高精度失敗，嘗試使用較低精度
    try {
      console.log('🔍 嘗試使用平衡模式取得位置...');
      const loc = await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.Balanced,
      });
      setLocation(loc);
      console.log('✅ Location obtained (balanced):', {
        lat: loc.coords.latitude,
        lng: loc.coords.longitude
      });
    } catch (error2) {
      console.error('❌ Error getting location (balanced):', error2);
      Alert.alert('錯誤', '無法取得位置資訊\n請確認已開啟 GPS 定位功能');
    }
  }
};

const startRecording = async () => {
  if (!cameraRef || isRecording) return;

  setIsRecording(true);
  try {
    console.log('🎥 開始錄影...');
    const video = await cameraRef.recordAsync({
      maxDuration: 1, // 最多錄 1 秒
      quality: '720p',
    });

    setRecordedVideo(video.uri);
    setIsRecording(false);
    console.log('✅ Video recorded:', video.uri);

    // 錄影完成後自動進入下一步
    setTimeout(() => setStep(3), 500);
  } catch (error) {
    console.error('❌ Error recording video:', error);
    setIsRecording(false);

    // 如果錄影失敗，詢問是否跳過
    Alert.alert(
      '錄影失敗',
      '無法錄製影片。是否跳過此步驟？',
      [
        { text: '重試', style: 'cancel' },
        { 
          text: '跳過', 
          onPress: () => {
            setRecordedVideo('mock://skipped.mp4');
            setStep(3);
          }
        }
      ]
    );
  }
};

