const startRecording = async () => {
  if (!cameraRef || isRecording) {
    console.log('⚠️ Camera not ready or already recording');
    return;
  }

  setIsRecording(true);
  try {
    console.log('🎥 開始錄影...');

    // 使用 Promise 來控制錄影時間
    const recordingPromise = cameraRef.recordAsync({
      maxDuration: 1, // 最多錄 1 秒
      quality: '720p',
      mute: false,
    });

    // 等待錄影完成（最多 1 秒）
    const video = await recordingPromise;

    if (video && video.uri) {
      setRecordedVideo(video.uri);
      console.log('✅ Video recorded successfully:', video.uri);

      // 錄影完成後自動進入下一步
      setTimeout(() => setStep(3), 500);
    } else {
      throw new Error('Video URI is null');
    }

    setIsRecording(false);
  } catch (error) {
    console.error('❌ Error recording video:', error);
    console.error('錯誤詳情:', error.message);
    setIsRecording(false);

    // 如果錄影失敗，詢問是否跳過
    Alert.alert(
      '錄影失敗',
      `無法錄製影片: ${error.message}\n\n是否跳過此步驟？`,
      [
        { 
          text: '重試', 
          style: 'cancel',
          onPress: () => console.log('用戶選擇重試')
        },
        { 
          text: '跳過', 
          onPress: () => {
            console.log('⏭️ 用戶選擇跳過錄影');
            setRecordedVideo(`mock://skipped_${Date.now()}.mp4`);
            setStep(3);
          }
        }
      ]
    );
  }
};

const handleExportAll = async () => {
  try {
    console.log('🔄 開始匯出流程...');
    const success = await exportAllData();
    if (success) {
      Alert.alert('✅ 成功', '資料已匯出並可分享\n\n檔案名稱: emogo_exported_data.json');
    } else {
      Alert.alert('⚠️ 提示', '分享功能不可用，但資料已儲存到裝置');
    }
  } catch (error) {
    console.error('匯出錯誤:', error);
    Alert.alert('❌ 失敗', `資料匯出失敗:\n${error.message}`);
  }
};

