        arousal: record.arousal,
        dominance: record.dominance,
        notes: record.notes || ''
      })),
      vlog_records: vlogRecords.map(record => ({
        id: record.id,
        timestamp: record.timestamp,
        video_path: record.video_uri,
        duration: record.duration
      })),
